import sys,json
osvs={}; findings=[]
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: d=json.loads(line)
    except: continue
    if 'osv' in d: osvs[d['osv']['id']]=d['osv']
    if 'finding' in d: findings.append(d['finding'])
best={}
for f in findings:
    oid=f['osv']; lvl=f.get('trace') and 'called' if any(t.get('function') for t in f.get('trace',[])) else 'imported'
    # determine level
    lvl = 'CALLED' if f.get('trace') and f['trace'][0].get('function') else ('IMPORTED' if f.get('trace') and f['trace'][0].get('package') else 'REQUIRED')
    rank={'REQUIRED':0,'IMPORTED':1,'CALLED':2}
    if oid not in best or rank[lvl]>rank[best[oid][0]]:
        best[oid]=(lvl,f)
rows=[]
for oid,(lvl,f) in best.items():
    o=osvs.get(oid,{})
    mod=f['trace'][0].get('module','?') if f.get('trace') else '?'
    fixed=f.get('fixed_version','—')
    summ=o.get('summary','')[:95]
    rows.append((lvl,mod,oid,fixed,summ))
order={'CALLED':0,'IMPORTED':1,'REQUIRED':2}
rows.sort(key=lambda r:(order[r[0]],r[1]))
for lvl,mod,oid,fixed,summ in rows:
    print(f'{lvl:9} {mod:32} {oid:14} fix->{fixed:12} {summ}')
print()
from collections import Counter
print(Counter(r[0] for r in rows))
